#if DEBUG && os(iOS)
// Source-only SBJLayout integration fixture; no application target is included.
// All visual form content and interactive annotations are generated by SBJLayout.
import Foundation
import PDFKit
import UIKit

public enum RentalApplicationExample {
    private static let email = URL(string: "mailto:propertiesbyjovellc@gmail.com")!
    private static let labelFont = UIFont.systemFont(ofSize: 8)
    private static let headingFont = UIFont.boldSystemFont(ofSize: 10)

    private static func label(_ title: String) -> JCSText {
        JCSText(verbatim: title, font: labelFont)
    }

    private static func heading(_ title: String) -> JCSText {
        JCSText(verbatim: title, font: headingFont)
    }

    private static func field(_ title: String, _ id: String, chars: Int = 24) -> some Renderable {
        Grid(vertFlow: .init(.fixed(243)), rows: .init(gap: 1)) {
            label(title)
            JCSTextField(name: id, minChars: chars, height: 19)
        }
    }

    private static func duo(_ left: String, _ leftID: String, _ right: String, _ rightID: String) -> some Renderable {
        Grid(table: [.init(.fixed(243)), .init(.fixed(243))], rows: .init(gap: 1)) {
            field(left, leftID)
            field(right, rightID)
        }
    }

    private static func three(_ labelText: String, _ id: String) -> some Renderable {
        Grid(vertFlow: .init(.fixed(486)), rows: .init(gap: 1)) {
            label(labelText)
            JCSTextField(name: id, minChars: 52, height: 19)
        }
    }

    private static func yesNo(_ question: String, _ id: String) -> some Renderable {
        Grid(table: [.init(.fixed(115)), .init(.fixed(122))], rows: .init(gap: 0)) {
            label(question)
            JCSRadioGroup(name: id, options: [.init("Yes", value: "yes"), .init("No", value: "no")], side: 11, spacing: 13, font: labelFont)
        }
    }

    private static func header(_ logo: UIImage?) -> some Renderable {
        Grid(table: [.init(.fixed(90)), .init(.fixed(385))], rows: .init(gap: 0)) {
            JCSImage(logo, aspect: .fit)
            Grid(vertFlow: .init(.fixed(385)), rows: .init(gap: 1)) {
                heading("PROPERTIES BY JOVE LLC")
                heading("RENTAL APPLICATION")
                JCSLink(email, content: label("propertiesbyjovellc@gmail.com"))
            }
        }
    }

    private static func applicant(_ prefix: String) -> some Renderable {
        Grid(vertFlow: .init(.fixed(243)), rows: .init(gap: 3)) {
            heading(prefix == "tenant" ? "PROSPECTIVE TENANT" : "SPOUSE / CO-TENANT")
            field("Full Name", "\(prefix).name")
            field("Social Security Number", "\(prefix).ssn")
            field("Date of Birth", "\(prefix).dob")
            field("Current Address", "\(prefix).address")
            field("Phone Number", "\(prefix).phone")
            field("Email (if different)", "\(prefix).email")
            label("In the past 7 years, have you:")
            yesNo("Filed for bankruptcy?", "\(prefix).bankruptcy")
            yesNo("Been evicted?", "\(prefix).eviction")
            yesNo("Defaulted on a mortgage?", "\(prefix).defaulted")
        }
    }

    private static func employment(_ prefix: String) -> some Renderable {
        Grid(vertFlow: .init(.fixed(243)), rows: .init(gap: 3)) {
            heading("EMPLOYMENT INFORMATION")
            field("Employer", "\(prefix).employer")
            field("Position", "\(prefix).position")
            field("Hire Date", "\(prefix).hireDate")
            field("Employer Address", "\(prefix).employerAddress")
            field("Employer Phone", "\(prefix).employerPhone")
            field("Salary (include frequency)", "\(prefix).salary")
            field("Other Income", "\(prefix).otherIncome")
            field("Source of Other Income", "\(prefix).otherIncomeSource")
        }
    }

    private static func reference(_ prefix: String, _ title: String) -> some Renderable {
        Grid(vertFlow: .init(.fixed(243)), rows: .init(gap: 2)) {
            heading(title)
            field("Previous Landlord", "\(prefix).landlord")
            field("Phone Number", "\(prefix).landlordPhone")
            field("Monthly Rent", "\(prefix).rent")
            field("Term / Dates of Tenancy", "\(prefix).tenancyDates")
            field("Bank", "\(prefix).bank")
            field("Personal Reference", "\(prefix).personalReference")
            field("Reference Phone Number", "\(prefix).referencePhone")
        }
    }

    private static func firstPage(_ logo: UIImage?) -> some Renderable {
        Grid(vertFlow: .init(.fixed(490)), rows: .init(gap: 7)) {
            header(logo)
            duo("Primary Email Address", "application.email", "Requested Move-In Date", "application.moveIn")
            Grid(table: [.init(.fixed(243)), .init(.fixed(243))], rows: .init(gap: 0)) {
                applicant("tenant")
                applicant("cotenant")
            }
            Grid(table: [.init(.fixed(243)), .init(.fixed(243))], rows: .init(gap: 0)) {
                employment("tenant")
                employment("cotenant")
            }
            heading("AUTOS OWNED")
            duo("Make / Model", "autos.0.makeModel", "Year / Monthly Payment", "autos.0.yearPayment")
            duo("Make / Model", "autos.1.makeModel", "Year / Monthly Payment", "autos.1.yearPayment")
        }
    }

    private static func secondPage(_ logo: UIImage?) -> some Renderable {
        Grid(vertFlow: .init(.fixed(490)), rows: .init(gap: 6)) {
            header(logo)
            heading("PERSONS TO OCCUPY THE HOME (AND NO OTHERS)")
            duo("Name", "occupants.0.name", "Relation / Date of Birth", "occupants.0.relationDOB")
            duo("Name", "occupants.1.name", "Relation / Date of Birth", "occupants.1.relationDOB")
            duo("Name", "occupants.2.name", "Relation / Date of Birth", "occupants.2.relationDOB")
            heading("PETS")
            duo("Type / Breed", "pets.0.typeBreed", "Count / Size / Weight", "pets.0.countSize")
            duo("Type / Breed", "pets.1.typeBreed", "Count / Size / Weight", "pets.1.countSize")
            Grid(table: [.init(.fixed(243)), .init(.fixed(243))], rows: .init(gap: 0)) {
                reference("tenant", "REFERENCES - APPLICANT")
                reference("cotenant", "REFERENCES - CO-TENANT")
            }
            heading("RELEASE OF INFORMATION AGREEMENT")
            JCSText(verbatim: "In signing this application, the undersigned states that the above information is warranted to be true and hereby authorizes the firm to whom this application is made to investigate the references herein listed, or statements or other data obtained pertaining to credit, rental history, financial responsibility, criminal background, and litigation history. The undersigned agrees that this application shall remain the property of the firm to whom this application is made. Information obtained through its investigation may be disclosed to the landlord or other firms. Falsification of data may permit termination of a future lease agreement, subject to applicable law.", font: labelFont, lines: 5...6)
            duo("Applicant Signature (type full name)", "tenant.signature", "Spouse / Co-Tenant Signature (type full name)", "cotenant.signature")
            duo("Applicant Signature Date", "tenant.signatureDate", "Co-Tenant Signature Date", "cotenant.signatureDate")
        }
    }

    /// Assemble the two individually SBJLayout-generated pages without flattening their widgets.
    /// Individual pages deliberately have stable boundaries; this fixed legal form must stay two pages.
    public static func create(logo: UIImage? = nil) -> PDFRenderResult {
        let generator = PDFGenerator(title: "Properties by Jove Rental Application", creator: "SBJLayout")
        let first = generator.form(firstPage(logo))
        let second = generator.form(secondPage(logo))
        let result = PDFDocument()
        if let document = first.document {
            for index in 0..<document.pageCount {
                if let page = document.page(at: index) { result.insert(page, at: result.pageCount) }
            }
        }
        if let document = second.document {
            for index in 0..<document.pageCount {
                if let page = document.page(at: index) { result.insert(page, at: result.pageCount) }
            }
        }
        return PDFRenderResult(data: result.dataRepresentation() ?? Data(), document: result, positions: [:])
    }
}

#endif
